var videoItem = element;
var parent = videoItem.parentNode;
if (!parent) return;
var neuroAnswer = null;
var children = Array.from(parent.children);
for (var i = 0; i < children.length; i++) {
  if (children[i].getAttribute('data-fast-name') === 'neuro_answer') {
    neuroAnswer = children[i];
    break;
  }
}
if (neuroAnswer && parent.contains(videoItem)) {
  parent.insertBefore(videoItem, neuroAnswer);
}
